// @ts-nocheck
export type Variant = {
  label: string;
  sku: string;
  price: number;
  stock: number;
};

export type Product = {
  id: string;
  name: string;
  brand: string;
  category: string;
  sku: string;
  description: string;
  image: string;
  imageColor: string;
  imageIcon: string;
  tag?: string;
  specs?: Record<string, string>;
  variants?: Variant[];
  price: number;
  priceRetail?: number;
  minQty: number;
  stock: number;
  onSale: boolean;
  salePrice?: number;
};

export type AppSettings = {
  businessName: string;
  tagline: string;
  logoText: string;
  accentColor: string;
  currency: string;
  whatsappNumber: string;
  contactEmail: string;
};

export function cloneProducts(products: Product[]): Product[] {
  return JSON.parse(JSON.stringify(products));
}

